WFI.Data.add("quest", {
  [7021] = { nil, nil, nil, nil, "Oh oh oh, salve. Sono il Greatfather Winter e, per gentile concessione della brava gente di Smokywood Pastures... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina di Smokywood Pastures\"... desidero augurarti un fantastico Feast of Winter Veil.\n\nSe quest'anno sei <stato/stata> <buono/buona>, forse riceverai i dolcetti di Smokywood Pastures come regalo per il Feast of Winter Veil. Evviva.", nil, nil, nil, nil, 0x296b27e3, "mmmm." },
  [7022] = { "È arrivato il Greatfather Winter!", "Parla con il Greatfather Winter; si trova vicino all'area dei venditori di Smokywood Pastures, a Ironforge.", nil, nil, "Oh oh oh, salve. Sono il Greatfather Winter e, per gentile concessione della brava gente di Smokywood Pastures... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina di Smokywood Pastures\"... desidero augurarti un fantastico Feast of Winter Veil.\n\nSe quest'anno sei <stato/stata> <buono/buona>, forse riceverai i dolcetti di Smokywood Pastures come regalo per il Feast of Winter Veil. Evviva.", 0xddbfaa79, 0x01d48083, nil, nil, 0x296b27e3, "..mm." },
  [7023] = { "È arrivato il Greatfather Winter!", "Parla con il Greatfather Winter; si trova vicino all'area dei venditori di Smokywood Pastures, a Ironforge.", "Buon Winter Veil, amico! Non dimenticare di salutare il Greatfather Winter, che ora si trova a Ironforge! Se quest'anno sei <stato/stata> <buono/buona>, riceverai doni meravigliosi il giorno del Feast of Winter Veil. Non dimenticare di dirgli cosa speri di ricevere quest'anno!\n\nE fa' scorta di dolcetti da regalare a chi è stato buono quest'anno. Abbiamo un'ottima scelta. Dalla nostra fattoria alla tua tavola: è la bontà genuina di Smokywood Pastures!", nil, "Oh oh oh, salve. Sono il Greatfather Winter e, per gentile concessione della brava gente di Smokywood Pastures... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina di Smokywood Pastures\"... desidero augurarti un fantastico Feast of Winter Veil.\n\nSe quest'anno sei <stato/stata> <buono/buona>, forse riceverai i dolcetti di Smokywood Pastures come regalo per il Feast of Winter Veil. Evviva.", 0xddbfaa79, 0x01d48083, 0x79ea1c26, nil, 0x296b27e3, "...m." },
  [7024] = { nil, nil, nil, nil, "Oh oh oh, salve. Sono il Greatfather Winter e, per gentile concessione della brava gente di Smokywood Pastures... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina di Smokywood Pastures\"... desidero augurarti un fantastico Feast of Winter Veil.\n\nSe quest'anno sei <stato/stata> <buono/buona>, forse riceverai i dolcetti di Smokywood Pastures come regalo per il Feast of Winter Veil. Evviva.", nil, nil, nil, nil, 0x296b27e3, "mmmm." },
  [7028] = { "Mali contorti", "Raccogli 25 Theradric Crystal Carvings per Willow, a Desolace.", "Le caverne di cristallo di Terramok si trovano a ovest, nel cuore di Maraudon... È un luogo antico, ricco di storia. E vorrei metterci le mani sopra, {class}. Reliquie degli dèi antichi giacciono nascoste dietro le porte giganti.\n\nSe sei <disposto/disposta> ad affrontare i mali contorti che si trovano a Maraudon, credo di poterti ricompensare adeguatamente. Raccogli le theradric crystal carving che trovi e riportamele.\n\nUna volta che avrò le incisioni, potrò... studiarle. Questi poteri sono rimasti a riposo troppo a lungo...", "Non fare domande!\n\nConosci la mia richiesta.", "Ah ah ah! Sapevo che saresti <tornato/tornata>.\n\n<Willow borbotta.>\n\n...Così facile da convincere.\n\n...Farebbe qualsiasi cosa per il giusto prezzo. Eh eh eh...", 0xeb949bcd, 0x2ae5de19, 0x1db4989e, 0x6691d3a6, 0xc35764ff, "....." },
  [7029] = { "La corruzione di Vyletongue", nil, nil, "Se riesci a guarire la pianta, ricomincerà a crescere. Dobbiamo fare ciò che possiamo, {name}...", "Grazie per avermela riportata, {name}. Con il liquido rimasto che mi hai portato posso continuare i miei studi.\n\nAnche se c'è ancora molto da fare, hai aiutato a guarire parte della corruzione che Vyletongue ha diffuso a Maraudon. Ti prego, prendi questo con la mia gratitudine.", 0x7d91904f, nil, nil, 0x364cece8, 0x5d10207c, ".mm.." },
  [7041] = { "La corruzione di Vyletongue", "Riempi la Coated Cerulean Vial nella pozza di cristallo arancione di Maraudon.\n\nUsa la Filled Cerulean Vial sulle Vylestem Vines per far emergere il Noxxious Scion corrotto.\n\nGuarisci 8 piante uccidendo questi Noxxious Scion, poi torna da Talendria, a Nijel's Point.", "Un satiro noto come Vyletongue ha corrotto le caverne di Maraudon, impedendo la crescita di molte delle piante al loro interno.\n\nPrendi questa fiala, {name}. Riempila nella pozza arancione corrotta che si trova nelle caverne; il rivestimento all'interno della fiala contrasterà le tossine, trasformandola in un agente curativo.\n\nTrova le Vylestem vine nelle caverne arancioni e usa su di esse il liquido purificato. La corruzione verrà eliminata dalla pianta, ma sappi che Vyletongue la controllerà ancora. Potrebbe usarla contro di te...", "Se riesci a guarire la pianta, ricomincerà a crescere. Dobbiamo fare ciò che possiamo, {name}...", "Grazie per avermela riportata, {name}. Con il liquido rimasto che mi hai portato posso continuare i miei studi.\n\nAnche se c'è ancora molto da fare, hai aiutato a guarire parte della corruzione che Vyletongue ha diffuso a Maraudon. Ti prego, prendi questo con la mia gratitudine.", 0x7d91904f, 0xa6b69606, 0xfab7c5bd, 0x364cece8, 0x5d10207c, "....." },
  [7044] = { "Le leggende di Maraudon", "Recupera le due parti dello Scepter of Celebras: il Celebrian Rod e il Celebrian Diamond.\n\nTrova un modo per parlare con Celebras.", "Un satiro oscuro chiamato Lord Vyletongue ha diffuso il suo male in queste grotte tortuose, avvelenando la mente di chiunque si trovi all'interno. Risiede ancora oltre i cristalli viola.\n\nVyletongue ha anche creato un simbolo vivente della sua corruzione chiamato Noxxion, che dimora oltre i cristalli arancioni. Insieme hanno rubato le due parti dello scettro di mio fratello. Celebras, mio fratello... vaga alla cieca là dentro, maledetto dalla corruzione.\n\nDevi aiutarlo! Trova i pezzi e parla con mio fratello... in qualche modo.", "Mi sono risvegliato da un incubo che sembrava non finire mai...", "Ora che hai recuperato le due parti del mio scettro, ho speranza che un giorno Maraudon possa liberarsi della corruzione Vyle.", 0x9af58870, 0xf9e13397, 0x41cb6b05, 0x82ff0f35, 0x9c0b7265, "....." },
  [7064] = { "La corruzione della terra e del seme", nil, nil, nil, nil, 0xf63286e3, nil, nil, nil, nil, ".mmmm" },
  [7065] = { "La corruzione della terra e del seme", "Uccidi la Princess Theradras e torna dal Keeper Marandis, a Nijel's Point, Desolace.", "Nelle profondità di Maraudon vive una creatura di caos e malvagità, {name}. La Princess Theradras è una forza elementale della terra in qualche modo legata agli Old Gods. Ere fa fu cercata da Zaetar, primo figlio di Cenarius. La prole della loro... relazione sono le creature note come centauri. Creature eternamente riconoscenti, i centauri uccisero Zaetar, e ora Theradras ne custodisce i resti. La mia missione qui è trovare chi sia abbastanza potente da uccidere Theradras, così da poter recuperare i resti di Zaetar prima di tornare a Stonetalon.", "Sento il peso di imporre la mia supplica alle razze mortali, ma non ci restano altre possibilità. Le razze di Azeroth hanno dimostrato senza ombra di dubbio di poter superare simili prove quando lavorano insieme, quindi è a loro che chiedo aiuto.\n\nSpero solo che basti.\n\nZaetar, fratello di Remulos, portò molte sofferenze in questo mondo, e alla fine ciò causò la sua stessa morte. C'è una lezione per tutti noi, se siamo abbastanza saggi da vederla.", "È una notizia meravigliosa, {name}! Grazie!\n\nAnche se mi preoccupa che tu non sia <riuscito/riuscita> a riportare i resti di Zaetar, chi sono io per mettere in dubbio la volontà del primogenito di Cenarius? Forse ora la volontà dei centauri si spezzerà e la loro sete di sangue diminuirà: possiamo solo sperarlo.\n\nIn caso di successo della nostra missione, mi sono stati dati questi oggetti per ricompensare chiunque ci abbia aiutati. Puoi sceglierne uno come segno di gratitudine.", 0xf63286e3, 0x7c3b8219, 0x4160b7a5, 0x014b5981, 0xc549a228, "....." },
  [7066] = { nil, "Cerca Remulos a Moonglade e dagli il Seed of Life.", "I centauri sventurati, i miei figli e le mie figlie, hanno bisogno del loro padre.\n\nGuardati intorno: questo luogo risuona di speranza e di tutto ciò che predica mio padre Cenarius. È nato da me! E non posso toglierlo loro... nemmeno per i loro crimini contro di me.\n\nMa c'è una cosa che vorrei chiederti per dare pace alla mente di mio fratello. Prendi questo... è il primo seme caduto dalla vita che i miei resti hanno nutrito. Digli che il mio spirito resta qui e che continuo a vivere. Sono sicuro che capirà.", "Hai addosso l'odore della corruzione, {name}... come molti avventurieri di questi tempi. Ma qualcosa in te è diverso. C'è qualcosa di cui sei <venuto/venuta> a parlarmi? Hai un'aura che mi sembra familiare, ma non riesco a capire perché.\n\nTi prego, ti scongiuro, dimmi perché hai chiesto udienza.", "Quindi mio fratello ha finalmente trovato la pace? Sono fiero di aver vissuto abbastanza per vedere questo giorno. In tutta la sua arroganza e la sua rabbia, pensavo davvero che fosse perduto per noi, ma questo... questo simbolo del suo sacrificio dimostra solo che non è perduto: è solo rinato. Prende il suo posto nella natura come era suo dovere.\n\nGrazie, {name}. Portandomi questo, hai assicurato un po' di quella speranza che credevo di aver perduto. Questo seme sarà importante per la gente di questa terra dilaniata dalla guerra un giorno... lo sento.", nil, 0xd69615e8, 0x3d27e50c, 0xd29e327e, 0x9f7959fd, "m...." },
  [7067] = { nil, "Leggi le Pariah's Instructions. Poi ottieni l'Amulet of Union da Maraudon e riportalo al Centaur Pariah, nel sud di Desolace.", "Anche se esiliato come eretico, le mie convinzioni restano vere: questo soltanto mi spinge avanti. Ma perché il mio destino si compia, mi serve l'aiuto di qualcuno di esterno... di nessuna tribù dei centauri.\n\nIl compito richiede che qualcuno entri nelle sacre sale di Maraudon, una tomba che il mio popolo protegge, dove possono entrare solo i più devoti.\n\nSe accetti di aiutarmi, basta un cenno del capo. Ti passerò una pergamena con le mie istruzioni. Leggila e rifletti sulle mie parole.", "Cosa hai deciso, {name}? Puoi aiutarmi? Metterai piede su suolo sacro per aiutarmi a forgiare una grande tribù di centauri!?", "Eccolo, {race}! Eccolo! Ora posso cominciare la grande impresa di unire le tribù. Grazie.\n\nPrendi questo per i tuoi sforzi, ti prego. Spero che la prossima volta che ci incontreremo sarà in circostanze molto diverse.", nil, 0x644fa901, 0x17cdfc7b, 0xa3331956, 0x76f3983f, "m...." },
  [7383] = { "La corona della terra", "Riempi l'Amethyst Phial e riportala a Corithras Moonrage, a Dolanaar.", "Ma non tutto andava bene con Teldrassil. I piani accurati di Staghelm per il nuovo albero del mondo avevano dato i frutti che sperava, ma c'era un piccolo problema, un problema a cui si possono attribuire molti dei guai di Teldrassil.\n\nMa di questo non parlerò ancora. Devi visitare l'ultimo pozzo lunare, a nord-ovest, nell'Oracle Glade. Sotto i rami dell'Oracle Tree si trova il primo e il più potente dei nostri pozzi. Prendi una fiala della sua acqua e torna da me.", "Insieme ai druidi, l'Oracle Tree e l'arcidruido hanno seguito con attenzione la crescita di Teldrassil. Ma anche se abbiamo una nuova casa, le nostre vite immortali non ci sono state restituite.", "Essere al cospetto dell'Oracle Tree... è quasi sentire la saggezza prendere forma. Lascia che continui il racconto...\n\nCresciuto Teldrassil, l'arcidruido chiese ai draghi la loro benedizione, come quella che i draghi avevano dato a Nordrassil nei tempi antichi. Ma Nozdormu, signore del tempo, rifiutò la sua benedizione e rimproverò il druido per la sua arroganza. D'accordo con Nozdormu, anche Alexstrasza rifiutò Staghelm, e senza la sua benedizione la crescita di Teldrassil è stata imperfetta e imprevedibile...", 0x6a9c354f, 0x00e3b1b6, 0xa9b364df, 0xb7686ed0, 0x195e31f7, "....." },
  [7624] = { "Ulathek il traditore", "Affronta Ulathek, poi porta The Traitor's Heart a Lord Banehollow, a Jaedenar.", "Vuoi entrare nelle mie grazie? Allora uccidi per me.\n\nIl mio servitore, Ulathek, è patetico per come striscia davanti a me, mentre trama con Lord Hel'nurath su Xoroth. Hel'nurath vuole usurpare il mio potere qui, e Ulathek è la sua spia...\n\nDimostra di servire me e non i miei rivali. Affronta Ulathek nei suoi alloggi, nella Shadow Hold a ovest. Digli che conosco il suo segreto e guarda la paura impadronirsi di lui. Poi portami il cuore del traditore!", "Sento già sulle labbra il sapore del cuore di Ulathek. Così dolce è la carne di un traditore...", "Ah, splendido! Dopo una settimana a marcire, questo cuore sarà una prelibatezza succulenta! Forse farò portare la testa di Ulathek e la metterò davanti a me mentre mangio...\n\nMi hai reso un servizio, {class}, e così la mia pazienza nei tuoi confronti è cresciuta. Di poco.", 0x4b8d3a3d, 0xd5b88347, 0xe4198aaa, 0x01497fb4, 0x88afdb8f, "....." },
  [7625] = { nil, "Compra della Xorothian Stardust da Ur'dan. Portala a Gorzeeki Wildeyes, nelle Burning Steppes.", "Così vieni da me in cerca di Xorothian Stardust? Vuoi aprire un portale verso Xoroth, il dominio di Hel'nurath, il mio rivale? Forse hai intenzione di rubargli uno dei suoi preziosi dreadsteed?\n\nMolto bene. Il mio servitore Ur'dan ha una scorta di Xorothian Stardust. Puoi ottenerla da lui... se puoi pagarne il prezzo.", "Sei <stato/stata> a Jaedenar, {name}? Hai preso la polvere di stelle da Lord Banehollow?", "Eccola! Non riesco a credere che tu l'abbia presa! Devi aver fatto un grosso affare con quel Dreadlord, oppure pagato una bella somma, o entrambe le cose!\n\nMor'zul avrà il suo inchiostro molto presto e potrà finalmente preparare la pergamena del glifo, così potrai aprire un portale verso Xoroth e farne uscire uno dei famosi dreadsteed!", nil, 0x4baa8da0, 0xfa59e779, 0x95c60713, 0x7a7c7622, "m...." },
  [7645] = { nil, "Procura 20 Enriched Manna Biscuits, l'ingrediente chiave del Manna-Enriched Horse Feed, per Merideth Carlson, a Southshore, nelle Hillsbrad Foothills. L'Argent Dawn è noto come unico fornitore di questi biscotti.\n\nDevi anche darle 50 monete d'oro per calmare la sua suscettibilità offesa.", "La Silver Hand mi credeva pazza quando dissi che potevo creare uno speciale mangime per cavalli capace di nutrire i cavalli spirituali. Tutti mi credevano pazza! Beh, ora è il momento della rivincita!\n\nPreparerò ciò che ti serve, <paladino/paladina>... <cosiddetto/cosiddetta> <campione/campionessa>... ma ti costerà. Per questa miscela mi servono biscotti speciali, gli Enriched Manna Biscuits venduti solo dall'Argent Dawn. Esigo anche, sì, esigo, dell'oro come risarcimento per le pene che ho sopportato!\n\nMostrami il sacrificio di cui ti vanti tanto, <paladino/paladina>.", "Sì, ora ti ho dimostrato che avevi torto, vero? Ho dimostrato a tutti che avevano torto! Avevo ragione io fin dall'inizio!!!", "Sì, e ora chi... aspetta... mi dai anche l'oro? Non sei <stato/stata> tu a darmi della pazza (anzi, mi hanno dato della svitata)... eppure sei <disposto/disposta> a sacrificarti anche per torti che non hai commesso?\n\nIo... io ti ho <giudicato/giudicata> male, {name}. Se ti servisse altro mangime per cavalli, vieni da me. Te lo darò gratis. Grazie... nobile {class}.\n\nPerò i soldi me li tengo: non sono così svitata da rinunciare a una fortuna.", nil, 0x5da63733, 0x9d18fe77, 0x76c3ccbb, 0xb4ce0e54, "m...." },
  [7788] = { "Sconfiggi gli invasori!", "Entra a Warsong Gulch e sconfiggi l'Horde, ottieni un Warsong Gulch Mark of Honor e torna dalla Sentinel Farsong, al Silverwing Grove.", "Oltre questa galleria troverai un campo di conflitto e tumulto, giovane {class}. L'Horde continua a devastare la nostra foresta sacra, abbattendo il fogliame sempreverde per alimentare le sue macchine da guerra.\n\nEntra a Warsong Gulch e difendi Silverwing Hold. Respingi le forze d'invasione dell'Horde!\n\nFallo e guadagnerai un talismano al merito. Portami un tale talismano, {name}, e ti ricompenserò.", "Hai combattuto a Warsong Gulch e difeso Silverwing Hold?", "Hai dimostrato il tuo valore nei nostri sforzi a Warsong Gulch. Continua ad aiutare la causa e portami altri Marks of Honor. Fallo, e guadagnerai ancora di più la nostra fiducia.", 0x55520e44, 0xfeb46d9a, 0xd5134582, 0x71ff749c, 0xf9915c4e, "....." },
  [7791] = { "Una donazione di lana", nil, nil, nil, "Magnifico! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaad71c6f, nil, nil, nil, 0xde0116d9, ".mmm." },
  [7792] = { "Una donazione di lana", nil, nil, "Al momento accettiamo donazioni di stoffa di lana. Una donazione di sessanta pezzi di stoffa di lana ti farà ottenere il pieno riconoscimento di Darnassus per la tua generosità. Le nostre scorte di lana sono tali che da te ci servirebbero solo sessanta pezzi in tutto; dovremmo riuscire a procurarcene abbastanza da altri nel reame per sostenere la raccolta.\n\nSe hai con te i sessanta pezzi di stoffa di lana e sei <pronto/pronta> a donarli, posso prenderli ora.", "Magnifico! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaad71c6f, nil, nil, 0x30fa2bb9, 0xde0116d9, ".mm.." },
  [7793] = { "Una donazione di seta", nil, nil, "Come per quasi tutti gli altri tessuti, le nostre scorte di seta sono ai minimi storici. Le nostre scorte sono tali che da te ci servirebbero solo sessanta pezzi di seta in tutto; dovremmo riuscire a raggiungere l'obiettivo con il sostegno di altri.\n\nUn dono generoso come la seta, aggiungerei, aumenterebbe di certo la tua reputazione nella comunità! Se hai con te i sessanta pezzi di stoffa di seta e sei <pronto/pronta> a donarli, posso prenderli ora.", "Magnifico! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaa4c5243, nil, nil, 0x12099df5, 0xde0116d9, ".mm.." },
  [7794] = { "Una donazione di mageweave", nil, nil, nil, "Magnifico! Ti ringraziamo per la tua generosa donazione, {name}!", 0x2c4ad0c3, nil, nil, nil, 0xde0116d9, ".mmm." },
  [7795] = { "Una donazione di runecloth", nil, nil, "{name}, hai contribuito moltissimo alla nostra raccolta di stoffa. Mentre lavoriamo sodo per ricostituire le riserve, un tipo di stoffa resta a livelli critici: la runecloth. Ne abbiamo un disperato bisogno, e speriamo che tu possa aiutarci come hai fatto in passato!\n\nSe vuoi, portami la runecloth che puoi cedere. All'inizio accetteremo una singola donazione di sessanta, poi vedremo.", "Fantastico: verranno usate subito, te lo assicuro. Grazie ancora per l'aiuto! Senza di te saremmo davvero persi.\n\nCon tutte le donazioni che hai fatto, accetterei di certo qualunque altra donazione di runecloth vorrai fare in futuro. Passa pure da me, e mi assicurerò di persona che le tue buone azioni non passino inosservate!", 0xaf5b02b1, nil, nil, 0x56be67b9, 0x690ecdf1, ".mm.." },
  [7798] = { "Una donazione di seta", nil, nil, "Come per quasi tutti gli altri tessuti, le nostre scorte di seta sono ai minimi storici. Le nostre scorte sono tali che da te ci servirebbero solo sessanta pezzi di seta in tutto; dovremmo riuscire a raggiungere l'obiettivo con il sostegno di altri.\n\nUn dono generoso come la seta, aggiungerei, aumenterebbe di certo la tua reputazione nella comunità! Se hai con te i sessanta pezzi di stoffa di seta e sei <pronto/pronta> a donarli, posso prenderli ora.", "Magnifico! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaa4c5243, nil, nil, 0x12099df5, 0xde0116d9, ".mm.." },
  [7799] = { "Una donazione di mageweave", nil, nil, "La mageweave scarseggia, e ci farebbe comodo il tuo aiuto per ricostituire le scorte! Contando sulla comunità intera, da te ci servirebbe solo una donazione di 60 pezzi di stoffa di mageweave per raggiungere il nostro obiettivo. Una simile generosità non passerebbe inosservata a Darnassus, te lo assicuro!\n\nSe hai con te i sessanta pezzi di stoffa di mageweave e sei <pronto/pronta> a donarli, posso prenderli ora.", "Magnifico! Ti ringraziamo per la tua generosa donazione, {name}!", 0x2c4ad0c3, nil, nil, 0x4ff1246f, 0xde0116d9, ".mm.." },
  [7800] = { "Una donazione di runecloth", nil, nil, "{name}, hai contribuito moltissimo alla nostra raccolta di stoffa. Mentre lavoriamo sodo per ricostituire le riserve, un tipo di stoffa resta a livelli critici: la runecloth. Ne abbiamo un disperato bisogno, e speriamo che tu possa aiutarci come hai fatto in passato!\n\nSe vuoi, portami la runecloth che puoi cedere. All'inizio accetteremo una singola donazione di sessanta, poi vedremo.", "Fantastico: verranno usate subito, te lo assicuro. Grazie ancora per l'aiuto! Senza di te saremmo davvero persi.\n\nCon tutte le donazioni che hai fatto, accetterei di certo qualunque altra donazione di runecloth vorrai fare in futuro. Passa pure da me, e mi assicurerò di persona che le tue buone azioni non passino inosservate!", 0xaf5b02b1, nil, nil, 0x56be67b9, 0x690ecdf1, ".mm.." },
  [7802] = { "Una donazione di lana", nil, nil, nil, "Magnifico! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaad71c6f, nil, nil, nil, 0xde0116d9, ".mmm." },
  [7803] = { "Una donazione di seta", nil, nil, "Come per quasi tutti gli altri tessuti, le nostre scorte di seta sono ai minimi storici. Le nostre scorte sono tali che da te ci servirebbero solo sessanta pezzi di seta in tutto; dovremmo riuscire a raggiungere l'obiettivo con il sostegno di altri.\n\nUn dono generoso come la seta, aggiungerei, aumenterebbe di certo la tua reputazione nella comunità! Se hai con te i sessanta pezzi di stoffa di seta e sei <pronto/pronta> a donarli, posso prenderli ora.", "Magnifico! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaa4c5243, nil, nil, 0x12099df5, 0xde0116d9, ".mm.." },
  [7804] = { "Una donazione di mageweave", nil, nil, nil, "Magnifico! Ti ringraziamo per la tua generosa donazione, {name}!", 0x2c4ad0c3, nil, nil, nil, 0xde0116d9, ".mmm." },
  [7805] = { "Una donazione di runecloth", nil, nil, "{name}, hai contribuito moltissimo alla nostra raccolta di stoffa. Mentre lavoriamo sodo per ricostituire le riserve, un tipo di stoffa resta a livelli critici: la runecloth. Ne abbiamo un disperato bisogno, e speriamo che tu possa aiutarci come hai fatto in passato!\n\nSe vuoi, portami la runecloth che puoi cedere. All'inizio accetteremo una singola donazione di sessanta, poi vedremo.", "Fantastico: verranno usate subito, te lo assicuro. Grazie ancora per l'aiuto! Senza di te saremmo davvero persi.\n\nCon tutte le donazioni che hai fatto, accetterei di certo qualunque altra donazione di runecloth vorrai fare in futuro. Passa pure da me, e mi assicurerò di persona che le tue buone azioni non passino inosservate!", 0xaf5b02b1, nil, nil, 0x56be67b9, 0x690ecdf1, ".mm.." },
  [7807] = { "Una donazione di lana", nil, nil, nil, "Magnifico! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaad71c6f, nil, nil, nil, 0xde0116d9, ".mmm." },
