  [7863] = { nil, nil, nil, nil, "Hai certamente cominciato a dimostrarci il tuo valore, {name}. Come ricompensa, prendi questo pacco di soccorso! Dentro troverai razioni e bende utilizzabili solo all'interno di Warsong Gulch.\n\nMan mano che continuerai a dimostrare il tuo valore nella Gulch, scoprirai che questi oggetti diventeranno disponibili all'acquisto. Le razioni diventano disponibili quando sei Friendly con noi, e le bende quando sei Honored.", nil, nil, nil, nil, 0x4d9a1c18, "mmmm." },
  [7864] = { nil, nil, nil, nil, "Hai certamente cominciato a dimostrarci il tuo valore, {name}. Come ricompensa, prendi questo pacco di soccorso! Dentro troverai razioni e bende utilizzabili solo all'interno di Warsong Gulch.\n\nMan mano che continuerai a dimostrare il tuo valore nella Gulch, scoprirai che questi oggetti diventeranno disponibili all'acquisto. Le razioni diventano disponibili quando sei Friendly con noi, e le bende quando sei Honored.", nil, nil, nil, nil, 0x4d9a1c18, "mmmm." },
  [7865] = { nil, nil, nil, nil, "Hai certamente cominciato a dimostrarci il tuo valore, {name}. Come ricompensa, prendi questo pacco di soccorso! Dentro troverai razioni e bende utilizzabili solo all'interno di Warsong Gulch.\n\nMan mano che continuerai a dimostrare il tuo valore nella Gulch, scoprirai che questi oggetti diventeranno disponibili all'acquisto. Le razioni diventano disponibili quando sei Friendly con noi, e le bende quando sei Honored.", nil, nil, nil, nil, 0x4d9a1c18, "mmmm." },
  [7866] = { nil, nil, nil, nil, "Hai certamente cominciato a dimostrarci il tuo valore, {name}. Come ricompensa, prendi questo pacco di soccorso! Dentro troverai razioni e bende utilizzabili solo all'interno di Warsong Gulch.\n\nMan mano che continuerai a dimostrare il tuo valore nella Gulch, scoprirai che questi oggetti diventeranno disponibili all'acquisto. Le razioni diventano disponibili quando sei Friendly con noi, e le bende quando sei Honored.", nil, nil, nil, nil, 0x4d9a1c18, "mmmm." },
