  [7868] = { nil, nil, nil, nil, "Hai certamente cominciato a dimostrarci il tuo valore, {name}. Come ricompensa, prendi questo pacco di soccorso! Dentro troverai razioni e bende utilizzabili solo all'interno di Warsong Gulch.\n\nMan mano che continuerai a dimostrare il tuo valore nella Gulch, scoprirai che questi oggetti diventeranno disponibili all'acquisto. Le razioni diventano disponibili quando sei Friendly con noi, e le bende quando sei Honored.", nil, nil, nil, nil, 0x4d9a1c18, "mmmm." },
  [7871] = { "Sconfiggi gli invasori!", "Entra a Warsong Gulch e sconfiggi l'Horde, ottieni un Warsong Gulch Mark of Honor e torna dalla Sentinel Farsong, al Silverwing Grove.", "Oltre questa galleria troverai un campo di conflitto e tumulto, giovane {class}. L'Horde continua a devastare la nostra foresta sacra, abbattendo il fogliame sempreverde per alimentare le sue macchine da guerra.\n\nEntra a Warsong Gulch e difendi Silverwing Hold. Respingi le forze d'invasione dell'Horde!\n\nFallo e guadagnerai un talismano al merito. Portami un tale talismano, {name}, e ti ricompenserò.", "Hai combattuto a Warsong Gulch e difeso Silverwing Hold?", "Hai dimostrato il tuo valore nei nostri sforzi a Warsong Gulch. Continua ad aiutare la causa e portami altri Marks of Honor. Fallo, e guadagnerai ancora di più la nostra fiducia.", 0x55520e44, 0xfeb46d9a, 0xd5134582, 0x71ff749c, 0xf9915c4e, "....." },
  [7872] = { "Sconfiggi gli invasori!", "Entra a Warsong Gulch e sconfiggi l'Horde, ottieni un Warsong Gulch Mark of Honor e torna dalla Sentinel Farsong, al Silverwing Grove.", "Oltre questa galleria troverai un campo di conflitto e tumulto, giovane {class}. L'Horde continua a devastare la nostra foresta sacra, abbattendo il fogliame sempreverde per alimentare le sue macchine da guerra.\n\nEntra a Warsong Gulch e difendi Silverwing Hold. Respingi le forze d'invasione dell'Horde!\n\nFallo e guadagnerai un Mark of Honor. Portamelo, {name}, e ti ricompenserò.", "Hai combattuto a Warsong Gulch e difeso Silverwing Hold?", "Hai dimostrato il tuo valore nei nostri sforzi a Warsong Gulch. Continua ad aiutare la causa e portami altri Marks of Honor. Fallo, e guadagnerai ancora di più la nostra fiducia.", 0x55520e44, 0xfeb46d9a, 0x682b535e, 0x71ff749c, 0xf9915c4e, "....." },
  [7873] = { "Sconfiggi gli invasori!", "Entra a Warsong Gulch e sconfiggi l'Horde, ottieni un Warsong Gulch Mark of Honor e torna dalla Sentinel Farsong, al Silverwing Grove.", "Oltre questa galleria troverai un campo di conflitto e tumulto, giovane {class}. L'Horde continua a devastare la nostra foresta sacra, abbattendo il fogliame sempreverde per alimentare le sue macchine da guerra.\n\nEntra a Warsong Gulch e difendi Silverwing Hold. Respingi le forze d'invasione dell'Horde!\n\nFallo e guadagnerai un Mark of Honor. Portamelo, {name}, e ti ricompenserò.", "Hai combattuto a Warsong Gulch e difeso Silverwing Hold?", "Hai dimostrato il tuo valore nei nostri sforzi a Warsong Gulch. Continua ad aiutare la causa e portami altri Marks of Honor. Fallo, e guadagnerai ancora di più la nostra fiducia.", 0x55520e44, 0xfeb46d9a, 0x682b535e, 0x71ff749c, 0xf9915c4e, "....." },
  [7883] = { "Lo gnomo più grande del mondo!", nil, nil, "Yebb Nebblegear vuole aggiungere nuovi talenti al suo spettacolo, e cerca in lungo e in largo lo gnomo più grande del mondo. Conosci qualche gnomo di dimensioni notevoli?\n\nBe', prima di trovare lo gnomo, vuole avere pronto il costume. Credo che una Barbaric Harness sarebbe una buona base per il costume: puoi fabbricarne qualcuna e portarmela? Fallo, e avrò per te una pila di biglietti della Darkmoon Faire...", "Oh, cielo, sono davvero grandi!! Non riesco a immaginare uno gnomo che ci entri comodamente, ma niente paura: se lo gnomo che troviamo non sarà abbastanza grande, posso fare delle modifiche al suo costume.\n\nMille grazie, {name}. Ecco i biglietti che ti avevo promesso.", 0xe283eba9, nil, nil, 0x4319c62d, 0x66786e48, ".mm.." },
  [7891] = { nil, nil, nil, "Sto lavorando a un nuovo costume, per quando avrò un banco tutto mio come la donna più forte del mondo! Ora cerco dei bracciali da indossare. Non devono coprire molto, perché la gente vuole vedere i miei muscoli, ma voglio comunque sfoggiare un po' di colore, capisci?\n\nChe ne dici dei Green Iron Bracers, {name}? Puoi farmi dei Green Iron Bracers? Se ci riesci, ho un bel mucchio di biglietti della Darkmoon Faire per te.", "Sì! Sono proprio quello che mi serve! Che bel colore, e mi lasciano comunque le braccia scoperte, così si vede quanto sono forti! Perfetti!\n\nEcco a te, {name}. Ecco i tuoi biglietti: divertiti!", nil, nil, nil, 0xb617dfba, 0x2bc703fc, "mmm.." },
  [7896] = { nil, nil, nil, "Quando finalmente avrò messo in piedi questo banco, vorrò farmi pubblicità! E quale modo migliore dei fuochi d'artificio?\n\nBe', qualcuno potrebbe pensare che l'odore di un calderone in cui ribollono le teste dei nemici attiri di più la folla, ma... qui c'è gente di ogni tipo. Quindi fuochi d'artificio siano!\n\nPortami dei Green Fireworks, {name}, e avrò per te una bella manciata di biglietti della Darkmoon Faire.", "Hai portato i fuochi d'artificio. Ottimo lavoro, {name}! Non vedo l'ora di accenderli e annunciare al mondo che il mio banco è pronto a partire! Devo ancora aspettare, temo parecchio, ma... sarò pronta quando sarò pronta, no?\n\nEcco i biglietti, {name}. Divertiti!", nil, nil, nil, 0xd0b2c4bd, 0x79ddc45f, "mmm.." },
  [7901] = { nil, nil, nil, "È incredibile a cosa la gente dia valore! Prendi, per esempio, un bastoncino di legno con attaccata una coda morbida e folta. Io e te potremmo pensare che una cosa del genere non valga granché... ma se dai a quella cianfrusaglia un bel nome come \"Savage Fuzz Tail\" e la metti in una bella scatola, la gente penserà che sia preziosa. La spazzatura diventa un tesoro!\n\nPortami delle Soft Bushy Tails dei lupi di Desolace e delle Badlands, e ti darò biglietti della Darkmoon Faire.", "Ben fatto, {name}! Queste code saranno ottimi premi per i nostri visitatori, e questo vuol dire visitatori felici... che ne parlano agli amici e portano altri visitatori!\n\nEcco i tuoi biglietti! Divertiti alla Darkmoon Faire... e non dimenticare di parlare di noi ai tuoi amici!", nil, nil, nil, 0x7ff937c5, 0x422a97ff, "mmm.." },
  [7907] = { nil, "Riporta il Beast Deck alla Darkmoon Faire quando arriva in città.", "Ora che hai riunito tutte le carte Beast in un mazzo, appare misteriosamente una nona carta con lo stesso dorso delle prime otto. Sopra c'è scritto: \"Riporta queste carte alla Darkmoon Faire e sarai ricompensato.\" Hai sentito dire che la fiera fa tappa a turno a Mulgore e a Goldshire ogni pochi mesi, quindi dovrai aspettare che torni da queste parti.", "Oh, povera me.", "Dunque hai messo insieme un mazzo di Beasts. Il tuo gesto di riportarlo a noi creerà un legame tra te e la Darkmoon che non sarà dimenticato presto. Permettimi di offrirti una delle carte maggiori della Darkmoon, come piccolo segno della nostra riconoscenza.", nil, 0x62dda1b1, 0x405afcfa, 0x9e26ead5, 0x5dda3bb5, "m...." },
  [7927] = { nil, "Riporta il Portals Deck alla Darkmoon Faire quando arriva in città.", "Ora che hai riunito tutte le carte Portal in un mazzo, appare misteriosamente una nona carta con lo stesso dorso delle prime otto. Sopra c'è scritto: \"Riporta queste carte alla Darkmoon Faire e sarai ricompensato.\" Hai sentito dire che la fiera fa tappa a turno a Mulgore e a Goldshire ogni pochi mesi, quindi dovrai aspettare che torni da queste parti.", "Vedo che sei <riuscito/riuscita> a completare un mazzo dei portali! Congratulazioni!", "Dunque hai messo insieme un mazzo di Portals. Il tuo gesto di riportarlo a noi creerà un legame tra te e la Darkmoon che non sarà dimenticato presto. Permettimi di offrirti una delle carte maggiori della Darkmoon, come piccolo segno della nostra riconoscenza.", nil, 0xff866ea6, 0x114b9c81, 0x38992949, 0x45adf59a, "m...." },
  [7928] = { nil, "Riporta il Warlords Deck alla Darkmoon Faire quando arriva in città.", "Ora che hai riunito tutte le carte Warlord in un mazzo, appare misteriosamente una nona carta con lo stesso dorso delle prime otto. Sopra c'è scritto: \"Riporta queste carte alla Darkmoon Faire e sarai ricompensato.\" Hai sentito dire che la fiera fa tappa a turno a Mulgore e a Goldshire ogni pochi mesi, quindi dovrai aspettare che torni da queste parti.", "Vedo che sei <riuscito/riuscita> a completare un mazzo dei signori della guerra! Congratulazioni!", "Dunque hai messo insieme un mazzo di Warlords. Il tuo gesto di riportarlo a noi creerà un legame tra te e la Darkmoon che non sarà dimenticato presto. Permettimi di offrirti una delle carte maggiori della Darkmoon, come piccolo segno della nostra riconoscenza.", nil, 0xb6535fe4, 0x79c29624, 0x04e4adf5, 0x9d09863b, "m...." },
  [7929] = { nil, "Riporta l'Elementals Deck alla Darkmoon Faire quando arriva in città.", "Ora che hai riunito tutte le carte Elemental in un mazzo, appare misteriosamente una nona carta con lo stesso dorso delle prime otto. Sopra c'è scritto: \"Riporta queste carte alla Darkmoon Faire e sarai ricompensato.\" Hai sentito dire che la fiera fa tappa a turno a Mulgore e a Goldshire ogni pochi mesi, quindi dovrai aspettare che torni da queste parti.", "Vedo che sei <riuscito/riuscita> a completare un mazzo degli elementali! Congratulazioni!", "Dunque hai messo insieme un mazzo di Elementals. Il tuo gesto di riportarlo a noi creerà un legame tra te e la Darkmoon che non sarà dimenticato presto. Permettimi di offrirti una delle carte maggiori della Darkmoon, come piccolo segno della nostra riconoscenza.", nil, 0xfea6f677, 0x6e234ab1, 0xc43ece46, 0xdac1d961, "m...." },
  [7937] = { "Il tuo destino ti attende...", "Vai all'Eastvale Logging Camp, nella Elwynn Forest, e scopri il tuo destino.", "\"Il tuo destino ti attende a Eastvale.\"\n\nIl responso che Sayge ti ha dato è appena tiepido al tatto. Stringendolo forte, vedi un'immagine dell'Eastvale Logging Camp nella Elwynn Forest. Concentrandoti meglio sull'immagine, vedi un pagliaio accanto a una stalla.", "Questo pagliaio somiglia a quello della tua visione.", "Frugando rapidamente nel pagliaio scopri una cassetta chiusa a chiave! A quanto pare hai trovato la tua fortuna!", 0xd4d31135, 0xc82083e8, 0x33dafe1f, 0xdd20eaed, 0x5a894296, "....." },
  [7938] = { "Il tuo destino ti attende...", nil, nil, nil, nil, 0xd4d31135, nil, nil, nil, nil, ".mmmm" },
  [7944] = { "Il tuo destino ti attende...", nil, nil, nil, nil, 0xd4d31135, nil, nil, nil, nil, ".mmmm" },
  [7945] = { "Il tuo destino ti attende...", nil, nil, nil, nil, 0xd4d31135, nil, nil, nil, nil, ".mmmm" },
  [7946] = { "La progenie di Jubjub", nil, nil, "Sono così felice che Jubjub non sia più dispersa. Adora talmente la Dark Iron ale che quando l'ho finita... è scappata a cercarne ancora!\n\nOra che Jubjub è tornata, voglio tutta la birra che riesco a trovare! Non voglio che scappi di nuovo!\n\nHai della Dark Iron Ale? Se ne hai, ti darò in cambio una delle uova di rana di Jubjub per ogni boccale...", "Grazie, {name}. Ecco il tuo uovo! Ci vorrà un po' prima che si schiuda, ma quando succederà avrai un'ottima mascotte!", 0xad05c1dd, nil, nil, 0x09b8849d, 0xb8311bf6, ".mm.." },
})
